class Solution {
  private int[] parent;

  public boolean canReachCorner(int xCorner, int yCorner, int[][] circles) {
    int n = circles.length;
    parent = new int[n + 4];
    for (int i = 0; i < parent.length; i++) parent[i] = i;
    final int LEFT = n, BOTTOM = n + 1, RIGHT = n + 2, TOP = n + 3;
    long X = xCorner, Y = yCorner;
    for (int i = 0; i < n; i++) {
      long x = circles[i][0], y = circles[i][1], r = circles[i][2];
      if (touches(x, y, r, 0, 0, 0, Y)) union(i, LEFT);
      if (touches(x, y, r, 0, 0, X, 0)) union(i, BOTTOM);
      if (touches(x, y, r, X, 0, X, Y)) union(i, RIGHT);
      if (touches(x, y, r, 0, Y, X, Y)) union(i, TOP);
      for (int j = 0; j < i; j++) {
        long x2 = circles[j][0], y2 = circles[j][1], r2 = circles[j][2];
        long dx = x - x2, dy = y - y2;
        if (dx * dx + dy * dy > (r + r2) * (r + r2)) continue;
        // the circles must meet inside the rectangle
        long sum = r + r2, px = x * r2 + x2 * r, py = y * r2 + y2 * r;
        if (px >= 0 && px <= X * sum && py >= 0 && py <= Y * sum) union(i, j);
      }
    }
    return find(LEFT) != find(RIGHT)
        && find(TOP) != find(BOTTOM)
        && find(LEFT) != find(BOTTOM)
        && find(TOP) != find(RIGHT);
  }

  // does the circle reach the wall segment (x1, y1)-(x2, y2) (axis aligned)?
  private boolean touches(long cx, long cy, long r, long x1, long y1, long x2, long y2) {
    long px = Math.max(x1, Math.min(x2, cx)), py = Math.max(y1, Math.min(y2, cy));
    long dx = cx - px, dy = cy - py;
    return dx * dx + dy * dy <= r * r;
  }

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  private void union(int a, int b) {
    parent[find(a)] = find(b);
  }
}
